function UIFishPoolGetCollectionPopupDialog:Awake()
    SetButtonAction(self.ImgBg, Bind(self, self.OnBtnClose))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._data = checkTable(argument.data)
    self._closeCb = (argument.cb)
    self._lastLevel = checkNumber(argument.lastLevel)

    self:FillSelf()
end

function UIFishPoolGetCollectionPopupDialog:FillSelf()
    local easterEggId = checkNumber(self._data.easterEgg)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(easterEggId)
    if goodsVo then
        CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
        CfUtils.FillText(self.TextCollectionName, goodsVo.name)

        local vo = FishingUtils.GetEasterEggsGroupVoByEggId(easterEggId)
        if vo then
            CfUtils.FillText(self.TextLaberlName, vo.name)
            local curNum, allNum = FishingUtils.GetEasterEggsGetNum(vo.id)
            CfUtils.FillText(self.TextNumber, "<color=#7fffec>"..curNum.."</color>/"..allNum)
            if curNum >= allNum then
                KTool.SetActive(self.ImgHasCompleted, true)
            end
        end
    end
end

function UIFishPoolGetCollectionPopupDialog:OnBtnClose()
    UIModule.CloseDialog(self.controller)

    if checkNumber(self._data.fishLevel) > self._lastLevel then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
            lastLevel = self._lastLevel,
            curLevel = self._data.fishLevel,
            levelUpType = Constants.UICultivateLevelUpFinishType.FishLevel
        }})
    end

    if self._closeCb then
        self._closeCb()
    end
end

